import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        /*
        Filter the incoming request based on certain rules and conditions.
        :param request: HashMap<String, Any>, the incoming request details
        :return: Bool, true if the request is allowed, false otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.filter(HashMap<String, Any>([('path', '/login'), ('method', 'POST')]))
        true

        */
        // Get request URI
        switch request.get("path") {
        case Some(pathAny):
            let requestUri = pathAny as String
            if this.is_start_with(requestUri) {
                return true
            }
        case None:
            // No path provided, deny
            return false
        }

        // Validate token and user info
        let tokenOpt = this.get_jwt_user(request)
        switch tokenOpt {
        case Some(tokenAny):
            let token = tokenAny as HashMap<String, Any>
            switch token.get("user") {
            case Some(userAny):
                let user = userAny as HashMap<String, Any>
                switch user.get("level") {
                case Some(levelAny):
                    let level = levelAny as Int64
                    if level > 2 {
                        this.set_current_user_info_and_log(user)
                        return true
                    } else {
                        return false
                    }
                case None:
                    return false
                }
            case None:
                return false
            }
        case None:
            return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        /*
        Check if the request URI starts with certain prefixes.
        Currently, the prefixes being checked are "/api" and "/login".
        :param request_uri: String, the URI of the request
        :return: Bool, true if the URI starts with certain prefixes, false otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.is_start_with('/api/data')
        true

        */
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        /*
        Get the user information from the JWT token in the request.
        :param request: HashMap<String, Any>, the incoming request details
        :return: HashMap<String, Any> or None, the user information if the token is valid, None otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.get_jwt_user(HashMap<String, Any>([('headers', HashMap<String, Any>([('Authorization', HashMap<String, Any>([('user', HashMap<String, Any>([('name', 'user1')])), ('jwt', 'user1'+DateTime.now().format("yyyy-MM-dd"))]))]))]))
        {'user': {'name': 'user1'}

        */
        // Extract headers
        switch request.get("headers") {
        case Some(headersAny):
            let headers = headersAny as HashMap<String, Any>
            // Extract Authorization
            switch headers.get("Authorization") {
            case Some(authorizationAny):
                let authorization = authorizationAny as HashMap<String, Any>
                // Extract user and jwt
                switch authorization.get("user") {
                case Some(userAny):
                    let user = userAny as HashMap<String, Any>
                    switch user.get("name") {
                    case Some(nameAny):
                        let name = nameAny as String
                        switch authorization.get("jwt") {
                        case Some(jwtAny):
                            let jwt = jwtAny as String
                            if jwt.startsWith(name) {
                                let parts = jwt.split(name)
                                if parts.size() >= 2 {
                                    let jwt_str_date = parts[1]
                                    // Compute 3 days ago date (string)
                                    let today_str = DateTime.now().format("yyyy-MM-dd")
                                    let three_days_ago_str = DateTime.parse(today_str, "yyyy-MM-dd").addDays(-3).format("yyyy-MM-dd")
                                    // If jwt date is older than or equal to 3 days ago, invalidate
                                    if jwt_str_date <= three_days_ago_str {
                                        return Option<HashMap<String, Any>>.None
                                    }
                                }
                            }
                            // token valid or does not start with user name => allow
                            return Option<HashMap<String, Any>>.Some(authorization)
                        case None:
                            return Option<HashMap<String, Any>>.None
                        }
                    case None:
                        return Option<HashMap<String, Any>>.None
                    }
                case None:
                    return Option<HashMap<String, Any>>.None
                }
            case None:
                return Option<HashMap<String, Any>>.None
            }
        case None:
            return Option<HashMap<String, Any>>.None
        }
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        /*
        Set the current user information and log the access.
        :param user: HashMap<String, Any>, the user information
        :return: Unit
        >>> filter = AccessGatewayFilter()
        >>> user = HashMap<String, Any>([('name', 'user1'), ('address', '127.0.0.1')])
        >>> filter.set_current_user_info_and_log(user)

        */
        let name = switch user.get("name") {
            case Some(nAny): nAny as String
            case None: ""
        }
        let host = switch user.get("address") {
            case Some(hAny): hAny as String
            case None: ""
        }
        let nowStr = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        println(name + host + nowStr)
    }
}

