import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    /*
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    */

    var binary_string: String

    public init(binary_string: String) {
        /*
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        */
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        /*
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'
        */
        let src: Array<Byte> = this.binary_string.toArray()
        var validCount: Int64 = 0
        var i: Int64 = 0
        while (i < src.size) {
            let b: Byte = src[i]
            if (b == 48u8 || b == 49u8) { // '0' or '1'
                validCount += 1
            }
            i += 1
        }

        let filtered: Array<Byte> = Array<Byte>(validCount, repeat: 0u8)
        var w: Int64 = 0
        i = 0
        while (i < src.size) {
            let b: Byte = src[i]
            if (b == 48u8 || b == 49u8) {
                filtered[w] = b
                w += 1
            }
            i += 1
        }

        this.binary_string = String.fromUtf8(filtered)
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        /*
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40.0}
        */
        let bytes: Array<Byte> = this.binary_string.toArray()
        let totalLen: Int64 = bytes.size

        var zeros: Int64 = 0
        var ones: Int64 = 0
        var i: Int64 = 0
        while (i < totalLen) {
            let b: Byte = bytes[i]
            if (b == 48u8) { // '0'
                zeros += 1
            } else if (b == 49u8) { // '1'
                ones += 1
            }
            i += 1
        }

        let result = HashMap<String, Float64>()
        if (totalLen == 0) {
            result.put("Zeroes", 0.0)
            result.put("Ones", 0.0)
            result.put("Bit length", 0.0)
            return result
        }

        let totalF: Float64 = totalLen as Float64
        result.put("Zeroes", (zeros as Float64) / totalF)
        result.put("Ones", (ones as Float64) / totalF)
        result.put("Bit length", totalF)
        return result
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'
        */
        let bytes = this.buildBytesFromBits()
        return String.fromUtf8(bytes)
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'
        */
        let bytes = this.buildBytesFromBits()
        return String.fromUtf8(bytes)
    }

    private func buildBytesFromBits(): Array<Byte> {
        // Convert binary_string (containing only '0' and '1') into bytes, 8 bits per byte.
        let bits: Array<Byte> = this.binary_string.toArray()
        let totalBits: Int64 = bits.size
        if (totalBits == 0) {
            return Array<Byte>(0, repeat: 0u8)
        }

        let numBytes: Int64 = (totalBits + 7) / 8
        let out: Array<Byte> = Array<Byte>(numBytes, repeat: 0u8)

        var byteIndex: Int64 = 0
        while (byteIndex < numBytes) {
            let start: Int64 = byteIndex * 8
            var end: Int64 = start + 8
            if (end > totalBits) {
                end = totalBits
            }

            var value: Int64 = 0
            var i: Int64 = start
            while (i < end) {
                value = (value << 1) | (if (bits[i] == 49u8) { 1 } else { 0 }) // '1' => 1, '0' => 0
                i += 1
            }

            out[byteIndex] = (value as Byte)
            byteIndex += 1
        }

        return out
    }
}

