import std.collection.ArrayList
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        /*
        Read the csv file by file_name, get the title and data from it
        :param file_name: String, name of the csv file
        :return title, data: (ArrayList<String>, ArrayList<ArrayList<String>>), first row is title, the rest is data
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        */
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        var reader: BufferedReader? = null
        try {
            reader = BufferedReader(FileReader(file_name))
            // Read title
            let first = reader.readLine()
            if first != null {
                let cols = first.split(",")
                var i: Int64 = 0
                while i < cols.size {
                    title.add(cols[i])
                    i += 1
                }
            }

            // Read data rows
            while true {
                let l = reader.readLine()
                if l == null {
                    break
                }
                // Skip empty lines
                if l.size == 0 {
                    continue
                }
                let parts = l.split(",")
                let row = ArrayList<String>()
                var j: Int64 = 0
                while j < parts.size {
                    row.add(parts[j])
                    j += 1
                }
                data.add(row)
            }
        } catch (e: Exception) {
            // On error, return what we have (possibly empty)
            if reader != null {
                try { reader.close() } catch (_: Exception) {}
            }
            return (title, data)
        }
        if reader != null {
            try { reader.close() } catch (_: Exception) {}
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        /*
        Write data into a csv file.
        :param file_name: String, name of the csv file
        :return: Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> data = ArrayList<ArrayList<String>>([ArrayList<String>(['a', 'b', 'c', 'd']), ArrayList<String>(['hElLo', 'YoU', 'ME', 'LoW'])])
        >>> csvProcessor.write_csv(data, 'write_test.csv')
        1
        */
        var writer: BufferedWriter? = null
        try {
            writer = BufferedWriter(FileWriter(file_name))
            var i: Int64 = 0
            while i < data.size {
                let row = data[i]
                var j: Int64 = 0
                while j < row.size {
                    writer.write(row[j])
                    if j < row.size - 1 {
                        writer.write(",")
                    }
                    j += 1
                }
                writer.write("\n")
                i += 1
            }
            try { writer.flush() } catch (_: Exception) {}
        } catch (e: Exception) {
            if writer != null {
                try { writer.close() } catch (_: Exception) {}
            }
            return 0
        }
        if writer != null {
            try { writer.close() } catch (_: Exception) {}
        }
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        /*
        Read a csv file into variable title and data.
        Only remain the N th (from 0) column data and Capitalize them, store the title and new data into a new csv file.
        Add '_process' suffix after old file name, as a new file name.
        :param N: Int64, the N th column(from 0)
        :param save_file_name, the name of file that needs to be processed.
        :return:Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        >>> csvProcessor.process_csv_data(0, 'read_test.csv')
        1
        >>> csvProcessor.read_csv('read_test_process.csv')
        (['a', 'b', 'c', 'd'], [['HELLO']])
        */
        let (title, data) = this.read_csv(save_file_name)

        // Extract N-th column and uppercase it
        let column_data = ArrayList<String>()
        var i: Int64 = 0
        while i < data.size {
            let row = data[i]
            if N >= 0 && N < row.size {
                let v = row[N].toUpperCase()
                column_data.add(v)
            } else {
                column_data.add("")
            }
            i += 1
        }

        // New data: first row is original title, second row is the new column_data as one CSV row
        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)
        new_data.add(column_data)

        // Build new file name: split at the first dot as in the Python version
        let nameParts = save_file_name.split(".")
        let baseName = nameParts.size > 0 ? nameParts[0] : save_file_name
        let new_file_name = baseName + "_process.csv"

        return this.write_csv(new_data, new_file_name)
    }
}

