class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        let n: Int32 = this.data.size()
        var i: Int32 = 0
        while (i < n) {
            sum += this.data.get(i)
            i += 1
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return Float64.NaN
        }
        var minVal: Float64 = this.data.get(0)
        var i: Int32 = 1
        while (i < n) {
            let v = this.data.get(i)
            if (v < minVal) {
                minVal = v
            }
            i += 1
        }
        return minVal
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return Float64.NaN
        }
        var maxVal: Float64 = this.data.get(0)
        var i: Int32 = 1
        while (i < n) {
            let v = this.data.get(i)
            if (v > maxVal) {
                maxVal = v
            }
            i += 1
        }
        return maxVal
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return Float64.NaN
        }
        var sum: Float64 = 0.0
        var i: Int32 = 0
        while (i < n) {
            sum += this.data.get(i)
            i += 1
        }
        let count: Float64 = n as Float64
        let mean: Float64 = sum / count

        var ssd: Float64 = 0.0
        i = 0
        while (i < n) {
            let d = this.data.get(i) - mean
            ssd += d * d
            i += 1
        }
        let variance: Float64 = ssd / count
        return round(variance, 2)
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return Float64.NaN
        }
        var sum: Float64 = 0.0
        var i: Int32 = 0
        while (i < n) {
            sum += this.data.get(i)
            i += 1
        }
        let count: Float64 = n as Float64
        let mean: Float64 = sum / count

        var ssd: Float64 = 0.0
        i = 0
        while (i < n) {
            let d = this.data.get(i) - mean
            ssd += d * d
            i += 1
        }
        let variance: Float64 = ssd / count
        let stdDev: Float64 = sqrt(variance)
        return round(stdDev, 2)
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let n: Int32 = this.data.size()
        if (n == 0) {
            return Float64.NaN
        }

        // Correlation of a vector with itself is 1.0 if variance > 0, otherwise undefined (NaN).
        var sum: Float64 = 0.0
        var i: Int32 = 0
        while (i < n) {
            sum += this.data.get(i)
            i += 1
        }
        let count: Float64 = n as Float64
        let mean: Float64 = sum / count

        var ssd: Float64 = 0.0
        i = 0
        while (i < n) {
            let d = this.data.get(i) - mean
            ssd += d * d
            i += 1
        }

        if (ssd == 0.0) {
            return Float64.NaN
        }
        return 1.0
    }
}

