import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var result = ""
        let n = ciphertext.count
        let s = normalizeShift(shift)
        var i: Int64 = 0
        while i < n {
            let ch = ciphertext[i]
            if isAlpha(ch) {
                let base = isUpper(ch) ? codeOf('A') : codeOf('a')
                let code = codeOf(ch)
                let shifted = mod26(code - base - s) + base
                result += String(charOf(shifted))
            } else {
                result += String(ch)
            }
            i += 1
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var result = ""
        let n = ciphertext.count
        let keyLen = key.count
        if keyLen == 0 {
            return ciphertext
        }
        var keyIndex: Int64 = 0
        var i: Int64 = 0
        while i < n {
            let ch = ciphertext[i]
            if isAlpha(ch) {
                let kch = key[keyIndex % keyLen]
                let shift = isAlpha(kch) ? (codeOf(toLower(kch)) - codeOf('a')) : 0
                let base = isUpper(ch) ? codeOf('A') : codeOf('a')
                let plainCode = mod26(codeOf(toLower(ch)) - codeOf('a') - shift) + codeOf('a')
                let decCharLower = charOf(plainCode)
                let decChar = isUpper(ch) ? toUpper(decCharLower) : decCharLower
                result += String(decChar)
                keyIndex += 1
            } else {
                result += String(ch)
            }
            i += 1
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let n = encrypted_text.count
        if rails <= 1 || rails >= n {
            return encrypted_text
        }

        // Build the zigzag rail index pattern for each position
        let pattern = ArrayList<Int64>()
        pattern.ensureCapacity(Int(n))
        var direction: Int64 = -1
        var row: Int64 = 0
        var i: Int64 = 0
        while i < n {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            pattern.add(row)
            row += direction
            i += 1
        }

        // Build the order of positions as they appear in the ciphertext when read rail-by-rail
        let order = ArrayList<Int64>()
        order.ensureCapacity(Int(n))
        var r: Int64 = 0
        while r < rails {
            var idx: Int64 = 0
            while idx < n {
                if pattern.get(Int(idx)) == r {
                    order.add(idx)
                }
                idx += 1
            }
            r += 1
        }

        // Prepare array to place decrypted characters in their original positions
        let plainChars = ArrayList<Char>()
        plainChars.ensureCapacity(Int(n))
        var filler: Int64 = 0
        while filler < n {
            plainChars.add(charOf(0))
            filler += 1
        }

        // Fill according to order mapping
        var j: Int64 = 0
        while j < n {
            let pos = order.get(Int(j))
            let ch = encrypted_text[j]
            plainChars.set(Int(pos), ch)
            j += 1
        }

        // Build result string
        var result = ""
        var k: Int64 = 0
        while k < n {
            result += String(plainChars.get(Int(k)))
            k += 1
        }
        return result
    }

    // Helpers

    private func normalizeShift(shift: Int64): Int64 {
        var s = shift % 26
        if s < 0 { s += 26 }
        return s
    }

    private func mod26(x: Int64): Int64 {
        var r = x % 26
        if r < 0 { r += 26 }
        return r
    }

    private func isAlpha(c: Char): Bool {
        let code = codeOf(c)
        return (code >= codeOf('A') && code <= codeOf('Z')) || (code >= codeOf('a') && code <= codeOf('z'))
    }

    private func isUpper(c: Char): Bool {
        let code = codeOf(c)
        return code >= codeOf('A') && code <= codeOf('Z')
    }

    private func toLower(c: Char): Char {
        if isUpper(c) {
            return charOf(codeOf(c) + 32)
        }
        return c
    }

    private func toUpper(c: Char): Char {
        let code = codeOf(c)
        if code >= codeOf('a') && code <= codeOf('z') {
            return charOf(code - 32)
        }
        return c
    }

    private func codeOf(c: Char): Int64 {
        // Assuming Char to Int64 conversion via builtin
        return Int64(c)
    }

    private func charOf(code: Int64): Char {
        // Assuming Int64 to Char conversion via builtin
        return Char(code)
    }
}

