    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let lower = "abcdefghijklmnopqrstuvwxyz"
        let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        let n: Int = plaintext.length()
        var i: Int = 0
        var ciphertext: String = ""

        let s: Int = (((shift % 26) + 26) % 26).toInt()

        while (i < n) {
            let ch: String = plaintext.substring(i, i + 1)

            let idxLower: Int = lower.indexOf(ch)
            if (idxLower >= 0) {
                let newIdx: Int = (idxLower + s) % 26
                ciphertext = ciphertext + lower.substring(newIdx, newIdx + 1)
                i = i + 1
                continue
            }

            let idxUpper: Int = upper.indexOf(ch)
            if (idxUpper >= 0) {
                let newIdx: Int = (idxUpper + s) % 26
                ciphertext = ciphertext + upper.substring(newIdx, newIdx + 1)
                i = i + 1
                continue
            }

            ciphertext = ciphertext + ch
            i = i + 1
        }

        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let lower = "abcdefghijklmnopqrstuvwxyz"
        let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        let keyLower: String = this.key.toLower()
        let keyLen: Int = keyLower.length()

        var keyIndex: Int = 0
        var encrypted: String = ""

        let n: Int = plain_text.length()
        var i: Int = 0

        while (i < n) {
            let ch: String = plain_text.substring(i, i + 1)

            let idxLower: Int = lower.indexOf(ch)
            if (idxLower >= 0) {
                let kpos: Int = keyIndex % keyLen
                let kch: String = keyLower.substring(kpos, kpos + 1)
                let shift: Int = lower.indexOf(kch)
                let newIdx: Int = (idxLower + shift) % 26
                encrypted = encrypted + lower.substring(newIdx, newIdx + 1)
                keyIndex = keyIndex + 1
                i = i + 1
                continue
            }

            let idxUpper: Int = upper.indexOf(ch)
            if (idxUpper >= 0) {
                let kpos: Int = keyIndex % keyLen
                let kch: String = keyLower.substring(kpos, kpos + 1)
                let shift: Int = lower.indexOf(kch)
                let newIdx: Int = (idxUpper + shift) % 26
                // compute as lower then uppercase to preserve mapping
                let encLower: String = lower.substring(newIdx, newIdx + 1)
                encrypted = encrypted + encLower.toUpper()
                keyIndex = keyIndex + 1
                i = i + 1
                continue
            }

            encrypted = encrypted + ch
            i = i + 1
        }

        return encrypted
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        let n: Int = plain_text.length()
        let r: Int = rails.toInt()

        if (r <= 1 || r >= n) {
            return plain_text
        }

        let rows = ArrayList<String>()
        var i: Int = 0
        while (i < r) {
            rows.add("")
            i = i + 1
        }

        var row: Int = 0
        var dir: Int = 1

        var idx: Int = 0
        while (idx < n) {
            let ch: String = plain_text.substring(idx, idx + 1)
            rows.set(row, rows.get(row) + ch)

            if (row == 0) {
                dir = 1
            } else if (row == r - 1) {
                dir = -1
            }
            row = row + dir
            idx = idx + 1
        }

        var encrypted: String = ""
        var j: Int = 0
        while (j < r) {
            encrypted = encrypted + rows.get(j)
            j = j + 1
        }

        return encrypted
    }
}

