import std.math.numeric.Decimal
import std.collection.ArrayList

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        */
        // 1. Transform and prepare to postfix
        prepare(transform(expression))

        // 2. Evaluate postfix
        let result_stack = ArrayList<Decimal>()
        for (token in postfix_stack) {
            if (!ExpressionCalculator.is_operator(token)) {
                let valueStr = replaceAll(token, "~", "-")
                result_stack.add(Decimal(valueStr))
            } else {
                let second_value = result_stack.removeLast()
                let first_value = result_stack.removeLast()
                let result = ExpressionCalculator._calculate(first_value, second_value, token)
                result_stack.add(result)
            }
        }

        // 3. Final result
        let finalDec = result_stack.removeLast()
        return Float64(finalDec)
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        // Clear previous state
        while (postfix_stack.size() > 0) {
            _ = postfix_stack.removeLast()
        }

        let op_stack = ArrayList<String>()
        op_stack.add(",")

        let arr = toCharArray(expression)
        var current_index: Int64 = 0
        var count: Int64 = 0

        var i: Int64 = 0
        while (i < arr.size()) {
            let current_op = arr.get(i)
            if (ExpressionCalculator.is_operator(current_op)) {
                if (count > 0) {
                    postfix_stack.add(joinRange(arr, current_index, count))
                }
                let peek_op = op_stack.last()
                if (current_op == ")") {
                    while (op_stack.last() != "(") {
                        postfix_stack.add(op_stack.removeLast())
                    }
                    _ = op_stack.removeLast() // pop '('
                } else {
                    var p = peek_op
                    while (current_op != "(" && p != "," && compare(current_op, p)) {
                        postfix_stack.add(op_stack.removeLast())
                        p = op_stack.last()
                    }
                    op_stack.add(current_op)
                }

                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
            i += 1
        }

        if (count > 1 || (count == 1 && !ExpressionCalculator.is_operator(arr.get(current_index)))) {
            postfix_stack.add(joinRange(arr, current_index, count))
        }

        while (op_stack.last() != ",") {
            postfix_stack.add(op_stack.removeLast())
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true

        */
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true

        */
        let c = (cur == "%") ? "/" : cur
        let p = (peek == "%") ? "/" : peek
        return precedence(p) >= precedence(c)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0

        */
        if (current_op == "+") {
            return first_value + second_value
        } else if (current_op == "-") {
            return first_value - second_value
        } else if (current_op == "*") {
            return first_value * second_value
        } else if (current_op == "/") {
            return first_value / second_value
        } else if (current_op == "%") {
            // Modulo using definition: a % b = a - b * (a / b)
            let q = first_value / second_value
            return first_value - second_value * q
        } else {
            // Unexpected operator, return 0
            return Decimal("0")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"

        */
        var expr = removeWhitespaces(expression)
        expr = removeTrailingEquals(expr)

        let arr = toCharArray(expr)

        var i: Int64 = 0
        while (i < arr.size()) {
            let c = arr.get(i)
            if (c == "-") {
                if (i == 0) {
                    arr.set(i, "~")
                } else {
                    let prev_c = arr.get(i - 1)
                    if (prev_c == "+" || prev_c == "-" || prev_c == "*" || prev_c == "/" || prev_c == "(" || prev_c == "E" || prev_c == "e") {
                        arr.set(i, "~")
                    }
                }
            }
            i += 1
        }

        if (arr.size() > 1 && arr.get(0) == "~" && arr.get(1) == "(") {
            arr.set(0, "-")
            return "0" + joinRange(arr, 0, arr.size())
        } else {
            return joinRange(arr, 0, arr.size())
        }
    }

    // -------------------- Helpers --------------------

    private func precedence(op: String): Int64 {
        if (op == "(") return 0
        if (op == ")") return 3
        if (op == "*") return 2
        if (op == "/") return 2
        if (op == "%") return 2
        if (op == "+") return 1
        if (op == "-") return 1
        if (op == ",") return -1
        return 0
    }

    private static func toCharArray(s: String): ArrayList<String> {
        let arr = ArrayList<String>()
        var i: Int64 = 0
        while (i < s.length()) {
            arr.add(s.substring(i, i + 1))
            i += 1
        }
        return arr
    }

    private static func joinRange(arr: ArrayList<String>, start: Int64, count: Int64): String {
        var res = ""
        var i: Int64 = start
        while (i < start + count) {
            res = res + arr.get(i)
            i += 1
        }
        return res
    }

    private static func removeWhitespaces(s: String): String {
        var res = ""
        var i: Int64 = 0
        while (i < s.length()) {
            let ch = s.substring(i, i + 1)
            if (!(ch == " " || ch == "\t" || ch == "\n" || ch == "\r")) {
                res = res + ch
            }
            i += 1
        }
        return res
    }

    private static func removeTrailingEquals(s: String): String {
        if (s.length() > 0 && s.substring(s.length() - 1, s.length()) == "=") {
            return s.substring(0, s.length() - 1)
        }
        return s
    }

    private static func replaceAll(s: String, from: String, to: String): String {
        var res = ""
        var i: Int64 = 0
        while (i < s.length()) {
            let ch = s.substring(i, i + 1)
            if (ch == from) {
                res = res + to
            } else {
                res = res + ch
            }
            i += 1
        }
        return res
    }
}

