import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var totalSum: Int64 = 0
        var P0DiagSum: Int64 = 0

        let colSums: ArrayList<Int64> = ArrayList<Int64>()
        var i: Int64 = 0
        while (i < k) {
            colSums.add(0)
            i += 1
        }

        i = 0
        while (i < k) {
            let row = testData.get(i)
            var rowSum: Int64 = 0

            var j: Int64 = 0
            while (j < k) {
                let val: Int64 = row.get(j)
                rowSum += val
                colSums.set(j, colSums.get(j) + val)
                j += 1
            }

            totalSum += rowSum
            P0DiagSum += row.get(i)
            i += 1
        }

        if (totalSum == 0) {
            return 0.0
        }

        var dotProduct: Int64 = 0
        i = 0
        while (i < k) {
            let row = testData.get(i)
            var rowSum: Int64 = 0
            var j: Int64 = 0
            while (j < k) {
                rowSum += row.get(j)
                j += 1
            }
            dotProduct += rowSum * colSums.get(i)
            i += 1
        }

        let sumF = Float64(totalSum)
        let P0 = Float64(P0DiagSum) / sumF
        let Pe = Float64(dotProduct) / (sumF * sumF)
        return (P0 - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        if (N == 0 || k == 0 || n <= 1) {
            return 0.0
        }

        var totalSum: Int64 = 0
        var P0: Float64 = 0.0

        let colSums: ArrayList<Int64> = ArrayList<Int64>()
        var jInit: Int64 = 0
        while (jInit < k) {
            colSums.add(0)
            jInit += 1
        }

        var i: Int64 = 0
        while (i < N) {
            let row = testData.get(i)
            var tempSumSquares: Int64 = 0

            var j: Int64 = 0
            while (j < k) {
                let v: Int64 = row.get(j)
                totalSum += v
                tempSumSquares += v * v
                colSums.set(j, colSums.get(j) + v)
                j += 1
            }

            let tempF = (Float64(tempSumSquares) - Float64(n)) / (Float64(n) * Float64(n - 1))
            P0 += tempF
            i += 1
        }

        if (totalSum == 0) {
            return 0.0
        }

        P0 = P0 / Float64(N)

        var Pe: Float64 = 0.0
        var c: Int64 = 0
        while (c < k) {
            let p_i = Float64(colSums.get(c)) / Float64(totalSum)
            Pe += p_i * p_i
            c += 1
        }

        if ((1.0 - Pe) == 0.0) {
            return 0.0
        }

        return (P0 - Pe) / (1.0 - Pe)
    }
}

