import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    private static func computeMRRForTuple(item: (ArrayList<Int64>, Int64)): Float64 {
        let (subList, totalNum) = item
        if totalNum == 0 {
            return 0.0
        }
        var i: Int32 = 0
        let n: Int32 = subList.size()
        while i < n {
            let v: Int64 = subList.get(i)
            if v != 0 {
                let denom: Float64 = Float64(i + 1)
                return 1.0 / denom
            }
            i = i + 1
        }
        return 0.0
    }

    private static func computeMAPForTuple(item: (ArrayList<Int64>, Int64)): Float64 {
        let (subList, totalNum) = item
        if totalNum == 0 {
            return 0.0
        }
        var i: Int32 = 0
        let n: Int32 = subList.size()
        var countRelevant: Int64 = 0
        var sumAP: Float64 = 0.0
        while i < n {
            let v: Int64 = subList.get(i)
            if v != 0 {
                countRelevant = countRelevant + 1
                sumAP = sumAP + (Float64(countRelevant) / Float64(i + 1))
            }
            i = i + 1
        }
        return sumAP / Float64(totalNum)
    }

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.mrr((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.mrr([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        1.0, [1.0]
        0.75, [1.0, 0.5]
        */
        // Single tuple case
        if data is (ArrayList<Int64>, Int64) {
            let item = data as (ArrayList<Int64>, Int64)
            let mr: Float64 = MetricsCalculator2.computeMRRForTuple(item)
            let out = ArrayList<Float64>()
            out.add(mr)
            return (mr, out)
        }

        // List case
        if data is ArrayList<Any> {
            let list = data as ArrayList<Any>
            if list.size() == 0 {
                let out = ArrayList<Float64>()
                out.add(0.0)
                return (0.0, out)
            }
            let separate = ArrayList<Float64>()
            var sum: Float64 = 0.0
            var i: Int32 = 0
            let n: Int32 = list.size()
            while i < n {
                let elemAny: Any = list.get(i)
                if !(elemAny is (ArrayList<Int64>, Int64)) {
                    throw IllegalArgumentException("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
                }
                let item = elemAny as (ArrayList<Int64>, Int64)
                let mr: Float64 = MetricsCalculator2.computeMRRForTuple(item)
                separate.add(mr)
                sum = sum + mr
                i = i + 1
            }
            let mean: Float64 = sum / Float64(separate.size())
            return (mean, separate)
        }

        throw IllegalArgumentException("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.map((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.map([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        0.41666666666666663, [0.41666666666666663]
        0.3333333333333333, [0.41666666666666663, 0.25]
        */
        // Single tuple case
        if data is (ArrayList<Int64>, Int64) {
            let item = data as (ArrayList<Int64>, Int64)
            let ap: Float64 = MetricsCalculator2.computeMAPForTuple(item)
            let out = ArrayList<Float64>()
            out.add(ap)
            return (ap, out)
        }

        // List case
        if data is ArrayList<Any> {
            let list = data as ArrayList<Any>
            if list.size() == 0 {
                let out = ArrayList<Float64>()
                out.add(0.0)
                return (0.0, out)
            }
            let separate = ArrayList<Float64>()
            var sum: Float64 = 0.0
            var i: Int32 = 0
            let n: Int32 = list.size()
            while i < n {
                let elemAny: Any = list.get(i)
                if !(elemAny is (ArrayList<Int64>, Int64)) {
                    throw IllegalArgumentException("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
                }
                let item = elemAny as (ArrayList<Int64>, Int64)
                let ap: Float64 = MetricsCalculator2.computeMAPForTuple(item)
                separate.add(ap)
                sum = sum + ap
                i = i + 1
            }
            let mean: Float64 = sum / Float64(separate.size())
            return (mean, separate)
        }

        throw IllegalArgumentException("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
    }
