class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        var out: String = ""
        var pos: Int64 = 0
        let length: Int64 = string.length

        while pos < length {
            if pos + 1 < length && string[pos] == r'&' && string[pos + 1] == r'#' {
                var start: Int64 = pos + 2
                var is_hex: Bool = false

                if start >= length {
                    return out
                }

                let first_char: Rune = string[start]
                if first_char == r'x' || first_char == r'X' {
                    is_hex = true
                    start += 1
                }

                if start >= length {
                    return out
                }

                var end: Int64 = start
                if is_hex {
                    while end < length && NumericEntityUnescaper.is_hex_char(string[end]) {
                        end += 1
                    }
                } else {
                    while end < length && string[end].isAsciiNumber() {
                        end += 1
                    }
                }

                if end < length && string[end] == r';' && end > start {
                    var val: Int64 = 0
                    var base: Int64 = 10
                    if is_hex {
                        base = 16
                    }

                    var idx: Int64 = start
                    while idx < end {
                        let dch: Rune = string[idx]
                        var digit: Int64 = -1

                        if is_hex {
                            if dch.isAsciiNumber() {
                                digit = dch.position() - r'0'.position()
                            } else {
                                let lower: Rune = dch.toAsciiLowerCase()
                                if lower >= r'a' && lower <= r'f' {
                                    digit = lower.position() - r'a'.position() + 10
                                } else {
                                    return out
                                }
                            }

                            if digit < 0 || digit >= 16 {
                                return out
                            }
                        } else {
                            if dch.isAsciiNumber() {
                                digit = dch.position() - r'0'.position()
                            } else {
                                return out
                            }

                            if digit < 0 || digit >= 10 {
                                return out
                            }
                        }

                        val = val * base + digit
                        idx += 1
                    }

                    let zero: Rune = r'\0'
                    let runeVal: Rune = zero.next(val)
                    out = out + runeVal.toString()
                    pos = end + 1
                    continue
                }
            }

            out = out + string[pos].toString()
            pos += 1
        }

        return out
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isAsciiHex()
    }
}

