import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let schemeEnd = this.url.indexOf("://")
        if (schemeEnd != -1) {
            return Option<String>.Some(this.url[0..schemeEnd])
        }
        return Option<String>.None
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let schemeEnd = this.url.indexOf("://")
        if (schemeEnd == -1) {
            return Option<String>.None
        }
        let urlWithoutScheme = this.url[schemeEnd + 3..this.url.size]
        let hostEnd = urlWithoutScheme.indexOf("/")
        if (hostEnd != -1) {
            return Option<String>.Some(urlWithoutScheme[0..hostEnd])
        }
        return Option<String>.Some(urlWithoutScheme)
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let schemeEnd = this.url.indexOf("://")
        if (schemeEnd == -1) {
            return Option<String>.None
        }
        let urlWithoutScheme = this.url[schemeEnd + 3..this.url.size]
        let hostEnd = urlWithoutScheme.indexOf("/")
        if (hostEnd != -1) {
            return Option<String>.Some(urlWithoutScheme[hostEnd..urlWithoutScheme.size])
        }
        return Option<String>.None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let queryStart = this.url.indexOf("?")
        if (queryStart == -1) {
            return Option<HashMap<String, String>>.None
        }

        let fragmentStart = this.url.indexOf("#")
        var endIndex: Int64 = this.url.size
        if (fragmentStart != -1 && fragmentStart > queryStart) {
            endIndex = fragmentStart
        }

        let queryString = this.url[queryStart + 1..endIndex]
        let params = HashMap<String, String>()

        if (queryString.size > 0) {
            var i: Int64 = 0
            while (i < queryString.size) {
                let rest = queryString[i..queryString.size]
                let ampRel = rest.indexOf("&")
                var pairStr: String
                if (ampRel != -1) {
                    pairStr = rest[0..ampRel]
                } else {
                    pairStr = rest
                }

                let eqIdx = pairStr.indexOf("=")
                if (eqIdx != -1) {
                    let key = pairStr[0..eqIdx]
                    let value = pairStr[eqIdx + 1..pairStr.size]
                    params.add(key, value)
                }

                if (ampRel != -1) {
                    i = i + ampRel + 1
                } else {
                    break
                }
            }
        }

        return Option<HashMap<String, String>>.Some(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragmentStart = this.url.indexOf("#")
        if (fragmentStart != -1) {
            return Option<String>.Some(this.url[fragmentStart + 1..this.url.size])
        }
        return Option<String>.None
    }
}

